def generate_wikilinks(ancestry_name, related_list):
    """Generate backlink section with wikilinks"""
    backlink = "Zurück zu: [[Ancestries-Overview]]"
    see_also = "Siehe auch: " + ", ".join([f"[[{name}]]" for name in related_list if name != ancestry_name])
    return f"\n\n---\n\n{backlink}\n\n{see_also}"

# Process each ancestry
for ancestry_name, data in sorted(ancestries_full.items()):
    # Extract content from ranges
    content_lines = []
    for start, end in data['ranges']:
        content_lines.extend(all_lines[start:end])

    content = ''.join(content_lines)

    # Create frontmatter
    frontmatter = '---\ntags: ["#Regeln/DrawSteel"]\n---\n\n'

    # Create wikilinks
    wikilinks = generate_wikilinks(ancestry_name, data['related'])

    # Combine everything
    full_content = frontmatter + content + wikilinks

    # File path
    file_name = f"{ancestry_name}.md"
    file_path = os.path.join(ancestry_base_path, file_name)

    # Write to file
    with open(file_path, 'w', encoding='utf-8') as f:
        f.write(full_content)

    print(f"✓ {file_name}: {len(content)} chars written")

print("\nAll ancestries updated!")

